-- Build 426 live runtime, independent transport probe and statistical rollup evidence.
create table if not exists app.master_build426_runtime_snapshots(
 snapshot_id uuid primary key,deployed_commit text,vercel_environment text,vercel_region text,process_uptime_sec bigint not null,node_version text not null,database_time timestamptz,migration_count integer not null,latest_migration text,latest_migration_at timestamptz,app_pool_total integer not null,app_pool_idle integer not null,app_pool_waiting integer not null,auth_pool_total integer not null,auth_pool_idle integer not null,auth_pool_waiting integer not null,performance_samples_24h integer not null,performance_failures_24h integer not null,performance_p95_ms_24h numeric,evidence_counts jsonb not null default '{}'::jsonb,observed_at timestamptz not null default now(),check(migration_count>=0 and process_uptime_sec>=0));
create table if not exists app.master_build426_transport_probe_events(
 probe_id uuid primary key,app_id text not null check(app_id in('ai-data-platform','rosevear-ai-hub','rosevear-comms-hub','icamp','yw','devilndove','rosiedazzlers')),origin text,origin_reachable boolean not null,origin_status integer,origin_latency_ms numeric,token_configured boolean not null,telemetry_status integer,telemetry_latency_ms numeric,telemetry_verified boolean not null,source_receipt_id uuid references app.master_build423_sysop_telemetry_receipts(receipt_id),source_commit text,detail text not null,observed_at timestamptz not null default now(),check(origin is null or origin~'^https://[A-Za-z0-9.-]+(?::[0-9]+)?$'));
create table if not exists app.master_build426_statistical_rollups(
 rollup_id uuid primary key,configured_origins integer not null,reachable_origins integer not null,token_configured_sources integer not null,verified_telemetry_sources integer not null,metrics jsonb not null default '{}'::jsonb,source_states jsonb not null default '[]'::jsonb,observed_at timestamptz not null default now(),check(configured_origins between 0 and 7 and reachable_origins between 0 and 7 and token_configured_sources between 0 and 7 and verified_telemetry_sources between 0 and 7));
alter table app.master_build426_runtime_snapshots enable row level security;alter table app.master_build426_runtime_snapshots force row level security;alter table app.master_build426_transport_probe_events enable row level security;alter table app.master_build426_transport_probe_events force row level security;alter table app.master_build426_statistical_rollups enable row level security;alter table app.master_build426_statistical_rollups force row level security;
create policy b426_runtime_read on app.master_build426_runtime_snapshots for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));create policy b426_probe_read on app.master_build426_transport_probe_events for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));create policy b426_rollup_read on app.master_build426_statistical_rollups for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));
create policy b426_runtime_insert on app.master_build426_runtime_snapshots for insert to ai_data_runtime with check(app.current_master_sysop_role() in('owner','operator'));create policy b426_probe_insert on app.master_build426_transport_probe_events for insert to ai_data_runtime with check(app.current_master_sysop_role() in('owner','operator'));create policy b426_rollup_insert on app.master_build426_statistical_rollups for insert to ai_data_runtime with check(app.current_master_sysop_role() in('owner','operator'));
create policy b426_runtime_protected_read on app.master_build426_runtime_snapshots for select to ai_data_protected_runtime using(true);create policy b426_probe_protected_read on app.master_build426_transport_probe_events for select to ai_data_protected_runtime using(true);create policy b426_rollup_protected_read on app.master_build426_statistical_rollups for select to ai_data_protected_runtime using(true);
grant select,insert on app.master_build426_runtime_snapshots,app.master_build426_transport_probe_events,app.master_build426_statistical_rollups to ai_data_runtime;grant select on app.master_build426_runtime_snapshots,app.master_build426_transport_probe_events,app.master_build426_statistical_rollups to ai_data_protected_runtime;revoke update,delete on app.master_build426_runtime_snapshots,app.master_build426_transport_probe_events,app.master_build426_statistical_rollups from ai_data_runtime,ai_data_protected_runtime;
